<template><section class="surface-card task-access-editor" aria-label="任务维护员授权"><h3>任务维护员授权</h3><p class="hint">维护员保留现有工作区的只读可见范围，代码与写操作按指定任务或分组授权。管理员与业务连接凭据管理仍单独保留。</p><label>维护员账户<input v-model.trim="username" class="input" maxlength="100"></label><button class="btn" :disabled="busy || !username" @click="load">读取授权</button><p v-if="error" class="inline-alert danger" role="alert">{{ error }}</p><p v-if="message" role="status">{{ message }}</p><form v-if="loaded" @submit.prevent="save"><fieldset :disabled="busy"><label>允许的任务编号（每行一个）<textarea v-model="tasks" class="input" rows="3" /></label><label>允许的任务分组（每行一个）<textarea v-model="groups" class="input" rows="3" /></label><label v-for="(label,key) in labels" :key="key" class="checkbox-row"><input v-model="form.capabilities" type="checkbox" :value="key">{{ label }}</label><button class="btn primary">保存任务授权</button></fieldset></form></section></template>
<script setup>
import { ref } from 'vue';import { api } from '../api';import {useUnsavedChanges,confirmUnsaved} from '../composables/useUnsavedChanges';
const props=defineProps({confirm:Function});const username=ref(''),tasks=ref(''),groups=ref(''),form=ref({}),loaded=ref(false),busy=ref(false),error=ref(''),message=ref('');const labels={run:'手动执行',schedule:'修改调度及启停',publish:'审查与发布任务代码',view_code:'查看任务源码'};let editing='';
const {saved:accessSaved}=useUnsavedChanges(()=>({tasks:tasks.value,groups:groups.value,capabilities:form.value.capabilities}),()=>loaded.value);
async function load(){if(props.confirm&&!await confirmUnsaved(props.confirm))return;busy.value=true;error.value='';try{const data=await api.taskAccess(username.value);editing=username.value;form.value=data;tasks.value=data.tasks.join('\n');groups.value=data.groups.join('\n');loaded.value=true;accessSaved();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function save(){if(username.value!==editing){error.value='账户已变化，请重新读取授权。';return;}busy.value=true;try{const lines=s=>s.split(/\r?\n/).map(v=>v.trim()).filter(Boolean);form.value=await api.saveTaskAccess(editing,{...form.value,tasks:lines(tasks.value),groups:lines(groups.value)});accessSaved();message.value='任务授权已保存，下一次请求生效。';error.value='';}catch(e){error.value=e.message;}finally{busy.value=false;}}
</script><style scoped>.task-access-editor,.task-access-editor fieldset{display:grid;gap:14px}.task-access-editor fieldset{border:0;padding:0;margin:0;min-width:0}.task-access-editor label{display:grid;gap:8px}.task-access-editor .checkbox-row{display:flex}</style>
